    const DETAILS = {"https://chat.deepseek.com/":{"tagline":"免费、中文友好、代码与推理能力突出的通用助手","asOf":"2026-10-23","tags":["免费","代码","推理","长文档","国内直连"],"facts":[{"label":"定价","value":"个人使用免费"},{"label":"平台","value":"网页 / App / 插件 / API"},{"label":"上下文","value":"128K（V3 系列）"},{"label":"开源","value":"权重与推理库开源"}],"intro":["深度求索（DeepSeek）是幻方量化旗下做通用模型的公司，网页版和 App 都能直接对话，注册即用、日常不收费。它的定位很明确：用远低于同行的训练成本，做出在数学与代码上能打的模型。","强项是「能落地」——贴一段报错能定位原因并给出可直接运行的改法，面对算法、数学和结构化写作时更稳，长文档也能一次读进去。","和其它助手相比，它有两个现实优势：中文表达自然，国内网络可直连。代价是高峰期会排队，图片只能理解不能生成。"],"capabilities":[{"group":"对话与写作","items":["多轮问答，能记住上下文","报告、邮件、文案的长文写作","多语言互译","改写、扩写、压缩与角色扮演"]},{"group":"代码","items":["按描述生成代码，覆盖主流语言","贴报错定位原因并给改法","解释陌生代码、拆分函数","跨语言改写与补测试"]},{"group":"数据与推理","items":["数学与逻辑推理，可展示思考过程","清洗表格、做统计分析","把数据转成柱状图 / 折线图 / 饼图","长文档要点提取与逐段追问"]},{"group":"接入与扩展","items":["开放平台 API，按 token 计费","开源权重，可本地部署","联网搜索取最新信息","上传图片做视觉理解"]}],"limits":["高峰期会排队或限流，重要任务别卡在截止前。","深度思考模式更慢但更准，简单问题开着反而浪费时间。","联网搜索默认关闭，需要在输入框手动开启。","能「看懂」图片，但不能生成图片。","单次上下文 128K（V3 系列），超长资料要分段喂。"],"steps":["打开 chat.deepseek.com，用手机号或邮箱注册登录。","直接在输入框提问；需要推理的题目打开「深度思考」。","上传 PDF / Word / 图片，让它基于内容回答，而不是只概括标题。","需要最新信息时打开联网搜索，并要求它给出处。","要接进自己的程序，去 platform.deepseek.com 申请 API Key。"],"modes":[{"name":"智能对话","desc":"日常问答、写作、改写，默认模式"},{"name":"深度思考","desc":"先推理再作答，适合数学、算法与多步分析"},{"name":"联网搜索","desc":"实时抓取网页信息，适合查最新动态"},{"name":"文件阅读","desc":"上传文档后提取要点、逐段追问"}],"scenarios":[{"icon":"💻","title":"写代码、改 bug","desc":"把报错和相关代码贴进去，让它定位原因并给出改法，比搜索引擎快一步。"},{"icon":"📄","title":"读长文档","desc":"上传 PDF 或粘贴长文，先要一份摘要，再逐段追问细节。"},{"icon":"🧠","title":"梳理思路","desc":"把模糊需求拆成步骤，或让它扮演反方专门挑毛病。"},{"icon":"✍️","title":"中文写作","desc":"改简历、写周报、润色文案，中文语感比多数海外模型更顺。"}],"models":[{"name":"DeepSeek-V3.2","kind":"通用","note":"当前对话主力，DSA 稀疏注意力，长文本训练与推理更快"},{"name":"DeepSeek-V3","kind":"通用","note":"MoE 架构，总参数 671B、每 token 激活 37B，128K 上下文"},{"name":"DeepSeek-R1","kind":"推理","note":"强化学习优化，数学、编程与自然语言推理见长"},{"name":"DeepSeek-R1-0528","kind":"推理","note":"660B，单任务可连续处理 30–60 分钟"},{"name":"DeepSeek-VL2","kind":"多模态","note":"视觉与语言理解，Tiny / Small / 标准版三档"},{"name":"DeepSeek-Prover-V2","kind":"垂直","note":"基于 Lean 4 的数学定理形式化证明"}],"highlights":["MLA 多头隐式注意力把 KV 缓存压到传统 Transformer 的 1/4，推理延迟明显下降。","多令牌预测（MTP）一次预测多个 token，训练效率与生成速度同时受益。","训练语料约 14.8 万亿 token，覆盖代码、数学证明与多语言文献。","开源周放出的 FlashMLA、DeepEP、DeepGEMM、3FS 等库，把推理与训练成本又压低一截。"],"links":[{"label":"官网对话","url":"https://chat.deepseek.com/"},{"label":"开放平台","url":"https://platform.deepseek.com/"},{"label":"开源仓库","url":"https://github.com/deepseek-ai"}]}}

